<section class="card daily-progress" aria-labelledby="daily-progress-title">
<div class="section-heading"><div><h2 id="daily-progress-title"><?= e(t('Your daily progress')) ?></h2><p class="muted"><?= e(t('See what you recorded, one day at a time.')) ?></p></div><form method="get" action="/" class="day-picker inline"><label class="sr-only" for="progress-date"><?= e(t('Review a day')) ?></label><input id="progress-date" type="date" name="date" max="<?= e(ui_date('Y-m-d')) ?>" value="<?= e($selectedDay) ?>" data-date-suggestions="off" required><button class="secondary"><?= e(t('Show day')) ?></button></form></div>
<nav class="day-links" aria-label="<?= e(t('Review day')) ?>"><a href="/?date=<?= e(ui_date('Y-m-d',strtotime($selectedDay.' -1 day'))) ?>"><?= e(t('← Previous day')) ?></a><?php if ($selectedDay!==ui_date('Y-m-d')): ?><a href="/"><?= e(t('Today')) ?></a><a href="/?date=<?= e(ui_date('Y-m-d',strtotime($selectedDay.' +1 day'))) ?>"><?= e(t('Next day →')) ?></a><?php else: ?><span class="muted"><?= e(t('Today ·')) ?> <?= e(ui_date('D, j M',strtotime($selectedDay))) ?></span><?php endif; ?></nav>
<?php if ($dailyProgress['has_activity']): ?><dl class="daily-metrics"><div><dt><?= e(t('Tasks completed')) ?></dt><dd><?= e($dailyProgress['tasks']) ?></dd></div><div><dt><?= e(t('Study time')) ?></dt><dd><?= e($dailyProgress['focus_minutes']) ?><small><?= e(t('minutes')) ?></small></dd></div><div><dt><?= e(t('Time for yourself')) ?></dt><dd><?= e($dailyProgress['personal_minutes']) ?><small><?= e(t('minutes')) ?></small></dd></div><div><dt><?= e(t('Spending')) ?></dt><dd><?= money($dailyProgress['expenses']) ?></dd></div></dl><?php endif; ?>
<?php if (!$dailyProgress['has_activity']): ?><p class="muted"><?= e(t('No activity recorded for this day. Add an expense, finish a task, or')) ?> <a href="/freedom#personal-time"><?= e(t('log some personal time')) ?></a>.</p><?php else: ?><p class="daily-extra"><?= e($dailyProgress['goal_steps']) ?> <?= e(t('goal steps completed ·')) ?> <?= e($dailyProgress['habits']) ?> <?= e(t('habit check-ins ·')) ?> <?= e($dailyProgress['expense_count']) ?> <?= e(t('expense entries')) ?><?php if ($dailyProgress['income_count']): ?> <?= e(t('? Income recorded')) ?> <?= money($dailyProgress['income']) ?><?php endif; ?></p><?php endif; ?>
<details class="progress-history"><summary><?= e(t('View your last 7 days')) ?> <span class="muted"><?= e(t('Study, personal time and completed actions')) ?></span></summary><div class="table-wrap"><table><thead><tr><th><?= e(t('Day')) ?></th><th><?= e(t('Tasks')) ?></th><th><?= e(t('Goal steps')) ?></th><th><?= e(t('Study')) ?></th><th><?= e(t('Personal time')) ?></th><th><?= e(t('Spending')) ?></th></tr></thead><tbody><?php foreach (array_reverse($dailyHistory) as $day): ?><tr><td><a href="/?date=<?= e($day['date']) ?>"><?= e(ui_date('D, j M',strtotime($day['date']))) ?></a></td><td><?= e($day['tasks']) ?></td><td><?= e($day['goal_steps']) ?></td><td><?= e($day['focus_minutes']) ?> <?= e(t('min')) ?></td><td><?= e($day['personal_minutes']) ?> <?= e(t('min')) ?></td><td><?= money($day['expenses']) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="footnote"><?= e(t('Completion dates are recorded from this update onward; older undated completions stay unknown. Study minutes use the day a session was completed.')) ?></p></details>
</section>
<?php if ($suggestions): ?><section class="next-dates" aria-label="<?= e(t('Suggested next actions from saved dates')) ?>"><?php foreach ($suggestions as $item): ?><a href="<?= e($item['route']) ?>"><span class="next-date-label <?= $item['when']==='Overdue' ? 'error-text' : '' ?>"><?= e($item['when']) ?> · <?= e($item['kind']) ?></span><strong><?= e($item['title']) ?></strong><span aria-hidden="true">→</span></a><?php endforeach; ?></section><?php endif; ?>
